CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (
  id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('admin','customer','recruiter')),
  recruiter_id TEXT NOT NULL DEFAULT '', recruiter_type TEXT NOT NULL DEFAULT '',
  is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS cities (id INTEGER PRIMARY KEY, city_name TEXT NOT NULL UNIQUE, province TEXT NOT NULL DEFAULT '', recruitment_status TEXT NOT NULL DEFAULT 'enabled', data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS factories (id INTEGER PRIMARY KEY, factory_name TEXT NOT NULL, city_id INTEGER REFERENCES cities(id), status TEXT NOT NULL DEFAULT 'enabled', data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_positions (id INTEGER PRIMARY KEY, position_name TEXT NOT NULL, factory_id INTEGER REFERENCES factories(id), city_id INTEGER REFERENCES cities(id), status TEXT NOT NULL DEFAULT 'enabled', featured INTEGER NOT NULL DEFAULT 0, data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS holiday_schedules (id INTEGER PRIMARY KEY, city_id INTEGER REFERENCES cities(id), date TEXT NOT NULL, kind TEXT NOT NULL, data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS city_links (id INTEGER PRIMARY KEY, city_id INTEGER REFERENCES cities(id), linked_city_id INTEGER REFERENCES cities(id), data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS recruiters (id INTEGER PRIMARY KEY, username TEXT NOT NULL, city_id INTEGER REFERENCES cities(id), status TEXT NOT NULL DEFAULT 'enabled', data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS knowledge_items (id INTEGER PRIMARY KEY, title TEXT NOT NULL, content TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'enabled', data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS unknown_questions (id INTEGER PRIMARY KEY, question TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agent_devices (id INTEGER PRIMARY KEY, device_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'enabled', data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS conversations (id INTEGER PRIMARY KEY, customer_name TEXT NOT NULL DEFAULT '', recruiter_id INTEGER REFERENCES recruiters(id), status TEXT NOT NULL DEFAULT 'active', data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS candidates (id INTEGER PRIMARY KEY, candidate_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agent_rules (id INTEGER PRIMARY KEY, rule_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'enabled', data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agent_evaluations (id INTEGER PRIMARY KEY, evaluation_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS old_friends (id INTEGER PRIMARY KEY, customer_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS status_records (id INTEGER PRIMARY KEY, status_name TEXT NOT NULL, data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activation_strategies (id INTEGER PRIMARY KEY, strategy_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'enabled', data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activation_devices (id INTEGER PRIMARY KEY, device_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'enabled', data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activation_scripts (id INTEGER PRIMARY KEY, script_name TEXT NOT NULL, content TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'enabled', data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activation_records (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL, nickname TEXT NOT NULL DEFAULT '', strategy TEXT NOT NULL DEFAULT 'no_reply', recruiter_id TEXT NOT NULL DEFAULT '', device_code TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending_review', summary TEXT NOT NULL DEFAULT '', script TEXT NOT NULL DEFAULT '', tier INTEGER NOT NULL DEFAULT 0, frozen_until TEXT, next_push_at TEXT, reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agent_messages (id INTEGER PRIMARY KEY, device_code TEXT NOT NULL, customer_id INTEGER NOT NULL, direction TEXT NOT NULL DEFAULT 'inbound', content TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'sent', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agent_conversations (id INTEGER PRIMARY KEY, device_code TEXT NOT NULL, customer_id INTEGER NOT NULL, nickname TEXT NOT NULL DEFAULT '', state TEXT NOT NULL DEFAULT 'active', recruit_status TEXT NOT NULL DEFAULT 'none', takeover INTEGER NOT NULL DEFAULT 0, unread INTEGER NOT NULL DEFAULT 0, city TEXT NOT NULL DEFAULT '', district TEXT NOT NULL DEFAULT '', last_msg TEXT NOT NULL DEFAULT '', last_msg_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(device_code,customer_id));
CREATE INDEX IF NOT EXISTS idx_service_positions_city ON service_positions(city_id);
CREATE INDEX IF NOT EXISTS idx_service_positions_factory ON service_positions(factory_id);
CREATE INDEX IF NOT EXISTS idx_factories_city ON factories(city_id);
CREATE INDEX IF NOT EXISTS idx_conversations_recruiter ON conversations(recruiter_id);
